def split_two_clusters(data, random_state=0):
    """Fit a 2-component GMM, return (region1_smaller, region2_larger, cutoff)."""
    data = np.asarray(data)
    gmm = GaussianMixture(n_components=2, random_state=random_state, n_init=5)
    labels = gmm.fit_predict(data.reshape(-1, 1))
    means = gmm.means_.flatten()
    small_label = np.argmin(means)
    large_label = np.argmax(means)
    region1 = data[labels == small_label]
    region2 = data[labels == large_label]
    # approximate cutoff: midpoint between the max of region1 and min of region2
    cutoff = (region1.max() + region2.min()) / 2 if len(region1) and len(region2) else None
    return region1, region2, cutoff
 
fr1_r1, fr1_r2, fr1_cutoff = split_two_clusters(freeze_rate_1)
fr2_r1, fr2_r2, fr2_cutoff = split_two_clusters(freeze_rate_2)
 
print(f'Freeze Rate 1: n={len(freeze_rate_1)}, cluster cutoff ~ {fr1_cutoff:.2f} um')
print(f'  Region 1 (small): n={len(fr1_r1)}, mean={fr1_r1.mean():.2f} +/- {fr1_r1.std(ddof=1):.2f} um')
print(f'  Region 2 (large): n={len(fr1_r2)}, mean={fr1_r2.mean():.2f} +/- {fr1_r2.std(ddof=1):.2f} um')
 
